<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import {api,changed,notify,ask} from '../lib/workspace';
import {normalized} from '../lib/format';
const props=defineProps({companyId:{type:Number,required:true}});
const emit=defineEmits(['dirty','busy']);
const data=ref(null),settings=ref({}),selected=ref(''),mode=ref('shared'),copyScope=ref('all'),search=ref(''),preview=ref(null),busy=ref(false),error=ref('');
let sequence=0;const baseline=ref('');
const dirty=computed(()=>!!data.value&&JSON.stringify(settings.value)!==baseline.value);
const plans=computed(()=>(data.value?.plans||[]).filter(p=>normalized(`${p.name} ${p.description} ${p.id}`).includes(normalized(search.value))));
const currentPlan=computed(()=>data.value?.plans.find(p=>p.id===data.value.binding?.global_plan_id));
watch(dirty,v=>emit('dirty',v));watch(busy,v=>emit('busy',v));
const root=()=>`/companies/${props.companyId}/accounting-settings`;
function accept(result){data.value=result;settings.value={...result.settings};baseline.value=JSON.stringify(settings.value);}
async function load(){const n=++sequence;data.value=null;preview.value=null;selected.value='';error.value='';busy.value=true;try{const r=await api(root());if(n===sequence)accept(r);}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
async function reload(){if(dirty.value&&!await ask({title:'Recarregar parâmetros?',message:'As alterações não salvas serão descartadas.',confirmLabel:'Recarregar'}))return;await load();}
watch(()=>props.companyId,load,{immediate:true});onUnmounted(()=>{sequence++;});
watch([selected,mode,copyScope],()=>{preview.value=null;});
async function save(){if(busy.value||!data.value?.capabilities.edit||!dirty.value)return;const n=sequence;busy.value=true;error.value='';try{const r=await api(root(),{method:'PUT',body:{version:data.value.version,settings:{...settings.value,default_cost_center_id:settings.value.default_cost_center_id||null}}});if(n===sequence){accept(r);changed();notify('Parâmetros contábeis salvos nesta empresa.');}}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
async function prepare(){if(busy.value||dirty.value||!selected.value)return;const n=sequence;busy.value=true;error.value='';try{const r=await api(`${root()}/plans/${selected.value}/preview`,{method:'POST',body:{mode:mode.value,copy_scope:copyScope.value}});if(n===sequence)preview.value=r;}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
async function apply(){if(busy.value||dirty.value||!preview.value?.can_confirm)return;const n=sequence,p=preview.value;busy.value=true;error.value='';try{await api(`${root()}/previews/${p.id}/confirm`,{method:'POST',body:{preview_hash:p.preview_hash,properties_reviewed:true,reason:'Seleção revisada do plano nos parâmetros contábeis da empresa.'}});if(n===sequence){preview.value=null;changed();notify('Plano de contas configurado para esta empresa.');busy.value=false;await load();}}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
async function detach(){if(busy.value||dirty.value||!data.value?.binding)return;const n=sequence;busy.value=true;error.value='';try{await api(`${root()}/detach`,{method:'POST',body:{version:data.value.binding.version,copy_scope:copyScope.value,reason:'Duplicação para plano próprio nos parâmetros contábeis da empresa.'}});if(n===sequence){changed();notify('Plano próprio criado, preservando os lançamentos.');busy.value=false;await load();}}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
</script>
<template><section class="accounting-settings" :aria-busy="busy">
<h3>Parâmetros contábeis da empresa</h3><p v-if="busy" role="status">Carregando configuração…</p>
<div v-if="error" class="message error" role="alert">{{error}} <button type="button" class="text-button" :disabled="busy" @click="reload">Atualizar configuração</button></div>
<template v-if="data">
<div class="message info"><strong>Plano em uso: </strong>{{currentPlan?.name||'Plano próprio / contas locais'}}<span v-if="data.binding"> · {{data.binding.mode==='shared'?'global compartilhado, sem duplicação':'próprio, adaptável'}}</span></div>
<p>Escolha o plano global que a empresa deve usar, como o 050 ou qualquer outro publicado. O vínculo compartilhado não duplica o plano. Alterar a seleção não transfere nem apaga lançamentos.</p>
<fieldset :disabled="busy" class="form-grid"><label>Localizar plano<input v-model="search" placeholder="Código ou nome do plano, ex.: 050"/></label><label>Plano de contas global<select v-model="selected"><option value="">Selecione um plano</option><option v-for="p in plans" :key="p.id" :value="p.id">{{p.name}} · {{p.record_count}} contas · versão #{{p.id}}</option></select></label><label>Forma de utilização<select v-model="mode"><option value="shared">Usar global, sem duplicar</option><option value="own">Duplicar para plano próprio</option></select></label><label v-if="mode==='own'||data.binding?.mode==='shared'">Cópia para plano próprio<select v-model="copyScope"><option value="all">Integral</option><option value="used">Somente usadas e contas-pai necessárias</option></select></label></fieldset>
<p v-if="!data.plans.length" class="message info">Nenhum plano global disponível. Importe e publique o plano em Contábil → Plano de contas → Ferramentas de importação e exportação.</p>
<p v-if="dirty" class="message info">Salve os padrões contábeis antes de aplicar ou duplicar um plano.</p>
<div class="actions"><button type="button" class="button outline" :disabled="busy||dirty||!selected||!data.capabilities.adopt" @click="prepare">Conferir seleção do plano</button><button v-if="data.binding?.mode==='shared'" type="button" class="button outline" :disabled="busy||dirty||!data.capabilities.edit" @click="detach">Criar plano próprio a partir do atual</button></div>
<section v-if="preview" class="plan-summary"><strong>{{preview.mode==='shared'?'Vínculo global sem cópia':'Cópia para plano próprio'}} · {{preview.record_count}} contas</strong><p>Contas existentes e seus identificadores serão preservados. Confira as propriedades e os conflitos antes de aplicar.</p><details><summary>Propriedades do plano</summary><pre>{{JSON.stringify(preview.plan?.properties,null,2)}}</pre></details><ul v-if="preview.conflicts?.length" class="message warning"><li v-for="(conflict,i) in preview.conflicts" :key="i">{{conflict.access_code}}: {{conflict.reason}}</li></ul><button type="button" class="button primary" :disabled="busy||dirty||!preview.can_confirm||!data.capabilities.adopt" @click="apply">Aplicar plano nesta empresa</button></section>
<h3>Padrões de novos lançamentos</h3><p>Preenchimento inicial editável para lançamentos manuais. Salvo separadamente do cadastro da empresa. Não altera lançamentos existentes nem movimentação importada.</p>
<div class="form-grid"><label>Histórico padrão<textarea v-model="settings.default_history" maxlength="1000" :disabled="busy||!data.capabilities.edit" placeholder="Opcional: texto sugerido ao iniciar um lançamento"/></label><label>Centro de custo padrão<select v-model="settings.default_cost_center_id" :disabled="busy||!data.capabilities.edit"><option :value="null">Sem padrão</option><option v-for="c in data.cost_centers" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}</option></select></label></div>
<div class="actions"><span>{{dirty?'Alterações não salvas':'Parâmetros salvos'}}</span><button type="button" class="button primary" :disabled="busy||!dirty||!data.capabilities.edit" @click="save">Salvar parâmetros contábeis</button></div>
</template></section></template>
<style scoped>.accounting-settings{display:grid;gap:14px}.accounting-settings h3,.accounting-settings p{margin:0}.accounting-settings p{line-height:1.5}.accounting-settings fieldset{border:0;padding:0;min-width:0}.plan-summary{padding:14px;border:1px solid var(--line);border-radius:8px;display:grid;gap:10px}.plan-summary pre{white-space:pre-wrap;overflow-wrap:anywhere}.accounting-settings .actions{flex-wrap:wrap}</style>
